import {
    IsString, IsOptional, IsUUID, IsIn, IsBoolean, MaxLength, MinLength, Matches, IsISO8601,
} from 'class-validator';

/** What a reader sends when a card is presented. It never says who the card belongs to. */
export class DeviceScanDto {
    /** Generated by the reader per physical tap; retries reuse it (idempotency key). */
    @IsUUID()
    eventId: string;

    @IsString()
    @MinLength(4)
    @MaxLength(40)
    uid: string;

    /** The reader's own clock — informational only; the server's time is authoritative. */
    @IsOptional()
    @IsISO8601()
    deviceTime?: string;

    /**
     * The direction the employee chose on the reader's own buttons.
     *
     * On-site attendance is decided at the reader: somebody picks Clock In or
     * Clock Out, presses Enter and taps. The portal records what they chose
     * and refuses it if it cannot be true — it does not quietly substitute
     * the other direction, because a reader that says "Clocked out" when the
     * employee asked to clock in is worse than one that says no.
     *
     * Omitted means "you decide", which is what the registration flow and
     * any future tap-and-go reader would send. The server then toggles, as
     * it always did.
     */
    @IsOptional()
    @IsIn(['clock_in', 'clock_out'])
    intent?: 'clock_in' | 'clock_out';
}

export class CreateDeviceDto {
    @IsString()
    @Matches(/^[A-Za-z0-9][A-Za-z0-9._-]{2,63}$/, {
        message: 'Device ID must be 3-64 characters: letters, digits, dot, dash or underscore.',
    })
    deviceId: string;

    @IsString()
    @MinLength(2)
    @MaxLength(120)
    name: string;

    @IsOptional()
    @IsString()
    @MaxLength(200)
    location?: string;
}

export class UpdateDeviceDto {
    @IsOptional()
    @IsString()
    @MinLength(2)
    @MaxLength(120)
    name?: string;

    @IsOptional()
    @IsString()
    @MaxLength(200)
    location?: string;

    @IsOptional()
    @IsBoolean()
    isActive?: boolean;
}

export class StartRegistrationDto {
    /** Which reader to use. Optional when exactly one reader is online. */
    @IsOptional()
    @IsUUID()
    deviceId?: string;

    @IsOptional()
    @IsIn(['register', 'replace'])
    mode?: 'register' | 'replace';

    /**
     * Issue the card even though the employee has not finished signing up.
     * Declared here deliberately: the global ValidationPipe whitelists, so an
     * undeclared field is dropped without a word and the override would look
     * as though it had been ignored.
     */
    @IsOptional()
    @IsBoolean()
    allowPending?: boolean;
}

export class RemoveCardDto {
    @IsString()
    @MinLength(3, { message: 'A reason of at least 3 characters is required.' })
    @MaxLength(500)
    reason: string;
}
